INSERT INTO `sentiment_analysis` (`id`, `tweet_id`, `preprocessing_id`, `username`, `tweet_text`, `processed_text`, `sentiment_label`, `confidence_score`, `positive_keywords`, `negative_keywords`, `neutral_keywords`, `labeling_method`, `labeled_at`, `labeled_by`, `created_at`) VALUES
(1762, 1, 588, NULL, 'Presiden Prabowo akan kesulitan benahi masalah bangsa yang carut-marut bilamana orang-orang Jokowi masih ada dalam kabinet. Orang-orang titipan Jokowi bukannya membantu tapi hanya menjadi beban Prabowo. Presiden Prabowo dalam kondisi dan posisi dilematis.', 'presiden prabowo sulit benah masalah bangsa carutmarut bilamana orangorang jokowi masih ada kabinet orangorang titip jokowi bukan bantu tetapi jadi beban prabowo presiden prabowo kondisi posisi lat', 'negatif', 1, 'presiden, ada, bantu, jadi, presiden', 'masalah, ada, kabinet, bukan, bantu, jadi, beban', '', 'auto', '2026-06-25 17:08:04', 1, '2026-06-25 17:08:04'),
(1763, 2, 589, NULL, '@hapuskanpinjol @kompascom Tito dan loyalis Jokowi lainnya yg berada di kabinet @prabowo tidak ada yg menganggap Prabowo Presiden mereka merasa bahwa atasannya adalah Jokowi mereka bekerja untuk kepentingan Jokowi. Hal spt ini kalau dibiarkan akan jd polemik &amp; bs jd ancaman terhadap presiden', 'tito loyalis jokowi lain yang ada kabinet tidak ada yang anggap prabowo presiden rasa bahwa atas jokowi kerja penting jokowi hal seperti biar jadi polemik amp bisa jadi ancam hadap presiden', 'negatif', 1, 'ada, ada, presiden, kerja, penting, biar, jadi, polemik, jadi, presiden', 'lain, yang, ada, kabinet, tidak, ada, yang, rasa, atas, penting, seperti, biar, jadi, jadi, ancam', '', 'auto', '2026-06-25 17:08:04', 1, '2026-06-25 17:08:04'),
(1764, 3, 590, NULL, '@124hmahHastuti1 Lebih dari pantas klau perlu hilang dari sejarah negeri ini. Kenapa dia diangakat lagi jd menteri d era presiden prabowo patut diduga karena cawe-cawe mulyono. Org ini jd instabilitas dlm kabinet merah putih. Peca', 'pantas kalau perlu hilang sejarah negeri kenapa diangakat lagi jadi menteri ada era presiden prabowo patut duga cawecawe mulyono orang jadi instabilitas dalam kabinet merah putih peca', 'negatif', 1, 'pantas, perlu, hilang, jadi, ada, presiden, patut, duga, jadi, dalam, merah', 'pantas, kalau, hilang, lagi, jadi, ada, patut, duga, jadi, kabinet, merah, putih', '', 'auto', '2026-06-25 17:08:04', 1, '2026-06-25 17:08:04'),
(1765, 4, 591, NULL, '@ferrykoto Dan sekarang tetap dipelihara oleh @prabowo jadilah kabinet omon2 . ', 'sekarang tetap pelihara jadi kabinet omon', 'positif', 0.4, 'tetap, pelihara, jadi', 'jadi, kabinet', '', 'auto', '2026-06-25 17:08:04', 1, '2026-06-25 17:08:04'),
(1766, 5, 592, NULL, '@Dito101074 Sayangnya pelemahan pemerintahan bapak prabowo ada di dalam kabinet pak prabowo sendiri Terutama pelaku-pelaku korupsi semasa jokowi Apakah bapak prabowo menyadari hal ini ????', 'sayang lemah perintah bapak prabowo ada kabinet pak prabowo sendiri utama pelakupelaku korupsi masa jokowi apakah bapak prabowo sadar hal', 'negatif', 1, 'sayang, lemah, ada, sadar', 'sayang, lemah, ada, kabinet, sendiri, korupsi, sadar', '', 'auto', '2026-06-25 17:08:04', 1, '2026-06-25 17:08:04'),
(1767, 6, 593, NULL, '@124hmahHastuti1 DIPECAT DARI KABINET PRABOWO !', 'pecat kabinet prabowo', 'negatif', 1, '', 'pecat, kabinet', '', 'auto', '2026-06-25 17:08:04', 1, '2026-06-25 17:08:04'),
