--
-- Structure for view `preprocessing_stats`
--
DROP TABLE IF EXISTS `preprocessing_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `preprocessing_stats`  AS SELECT `tp`.`processed_by` AS `processed_by`, count(0) AS `total_processed`, avg(`tp`.`word_count_before`) AS `avg_words_before`, avg(`tp`.`word_count_after`) AS `avg_words_after`, avg(`tp`.`removed_urls`) AS `avg_urls_removed`, avg(`tp`.`removed_mentions`) AS `avg_mentions_removed`, avg(`tp`.`removed_hashtags`) AS `avg_hashtags_removed`, avg(`tp`.`removed_stopwords`) AS `avg_stopwords_removed`, avg(`tp`.`normalized_words`) AS `avg_normalized_words`, avg(`tp`.`stemmed_words`) AS `avg_stemmed_words`, round(avg(((`tp`.`word_count_after` / `tp`.`word_count_before`) * 100)),2) AS `avg_reduction_percentage`, min(`tp`.`processed_at`) AS `first_processed`, max(`tp`.`processed_at`) AS `last_processed`, sum((case when (`tp`.`processing_status` = 'completed') then 1 else 0 end)) AS `successful_count`, sum((case when (`tp`.`processing_status` = 'failed') then 1 else 0 end)) AS `failed_count` FROM `text_preprocessing` AS `tp` WHERE (`tp`.`processing_status` in ('completed','failed')) GROUP BY `tp`.`processed_by` ;

